using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.CodeAnalysis;
using Nextended.CodeGen.Fluent;
using Nextended.Core.Attributes;

namespace Nextended.CodeGen.Generators.DtoGeneration;

/// <summary>
/// One generated DTO: the default DTO of a type (its first [AutoGenerateDto]) or one of its views (every further one).
/// The settings added for views are read from the attribute data by name, so the generator does not need the
/// Nextended.Core version that declares them.
/// </summary>
internal sealed class DtoUnit
{
    private DtoUnit(INamedTypeSymbol type, AttributeData? data, AutoGenerateDtoAttribute? viewAttr)
    {
        Type = type;
        Data = data;
        ViewAttr = viewAttr;
        UseViews = Strings(data, nameof(UseViews));
        OutputPath = String(data, nameof(OutputPath));
        foreach (var entry in Strings(data, nameof(PropertyNames)))
        {
            var parts = entry.Split('=');
            if (parts.Length == 2 && parts[0].Trim().Length > 0 && parts[1].Trim().Length > 0)
                PropertyNames[parts[0].Trim()] = parts[1].Trim();
            else
                MalformedPropertyNames.Add(entry);
        }
    }

    public static DtoUnit Default(INamedTypeSymbol type, AttributeData? data) => new(type, data, null);

    public static DtoUnit View(INamedTypeSymbol type, AttributeData? data, AutoGenerateDtoAttribute attr) => new(type, data, attr);

    public INamedTypeSymbol Type { get; }

    /// <summary>The attribute this unit comes from (for the default DTO of a derived type: the one of the base that declares it).</summary>
    public AttributeData? Data { get; }

    /// <summary>The merged settings of a view; null for a default DTO, whose settings come from ClassCfg as before.</summary>
    public AutoGenerateDtoAttribute? ViewAttr { get; }

    public bool IsView => ViewAttr != null;

    /// <summary>The key other settings address a view by: its GeneratedClassName.</summary>
    public string? Key => ViewAttr?.GeneratedClassName;

    public string[] UseViews { get; set; }
    public string? OutputPath { get; set; }

    /// <summary>The fluent rules of this view (View(...)); null for a default DTO and for views without fluent rules.</summary>
    public FluentTypeRules? FluentRules { get; set; }
    public Dictionary<string, string> PropertyNames { get; } = new(StringComparer.Ordinal);
    public List<string> MalformedPropertyNames { get; } = [];

    /// <summary>The view's own PreClassString, without the configuration's (an enum takes only its own).</summary>
    public string? OwnPreClassString => FluentRules?.Settings.TryGetValue(nameof(AutoGenerateDtoAttribute.PreClassString), out var fluent) == true
        ? fluent.Value as string
        : Data == null ? null : String(Data, nameof(AutoGenerateDtoAttribute.PreClassString));

    public Location Location => Data?.ApplicationSyntaxReference?.GetSyntax().GetLocation() ?? FluentRules?.Location ?? Location.None;

    /// <summary>Takes UseViews and OutputPath from fluent rules that set them.</summary>
    public void Apply(FluentTypeRules? rules)
    {
        if (rules?.Get(nameof(UseViews)) is string[] useViews)
            UseViews = useViews;
        if (rules != null && rules.Settings.TryGetValue(nameof(OutputPath), out var outputPath))
            OutputPath = outputPath.Value as string;
    }

    /// <summary>True when the property belongs to this unit's type or one of its bases.</summary>
    public bool Declares(IPropertySymbol property) => IsSelfOrBase(Type, property.ContainingType);

    /// <summary>True when <paramref name="candidate"/> is <paramref name="type"/> or one of its base types.</summary>
    public static bool IsSelfOrBase(INamedTypeSymbol type, INamedTypeSymbol? candidate)
    {
        if (candidate == null)
            return false;
        for (var t = type; t != null; t = t.BaseType)
            if (SymbolEqualityComparer.Default.Equals(t.OriginalDefinition, candidate.OriginalDefinition))
                return true;
        return false;
    }

    internal static string? String(AttributeData? data, string name)
        => Named(data, name) is { IsNull: false } value ? value.Value as string : null;

    internal static string[] Strings(AttributeData? data, string name)
        => Named(data, name) is { Kind: TypedConstantKind.Array, IsNull: false } value
            ? value.Values.Select(v => (v.Value as string)?.Trim()).Where(s => !string.IsNullOrEmpty(s)).Select(s => s!).ToArray()
            : [];

    private static TypedConstant? Named(AttributeData? data, string name)
    {
        if (data == null)
            return null;
        foreach (var argument in data.NamedArguments)
            if (argument.Key == name)
                return argument.Value;
        return null;
    }
}
